(() => {
  const row = [...document.querySelectorAll('#tree [draggable=true]')].find((r) => r.textContent.includes('a.txt'));
  const target = document.querySelector('.workspace-pane.active .pane.terminal');
  const data = new DataTransfer();
  row.dispatchEvent(new DragEvent('dragstart', { dataTransfer: data, bubbles: true }));
  target.dispatchEvent(new DragEvent('dragenter', { dataTransfer: data, bubbles: true, cancelable: true }));
  target.dispatchEvent(new DragEvent('dragover', { dataTransfer: data, bubbles: true, cancelable: true }));
  target.dispatchEvent(new DragEvent('drop', { dataTransfer: data, bubbles: true, cancelable: true }));
})()
